const closeM=()=>$("#ov").classList.remove("show");
function confirmM(t,msg,ok,fn){modal(`<h2>${t}</h2><div class="warn">⚠ ${msg}</div><div class="rw"><button class="btn" id="no">Cancel</button><button class="btn pr" id="yes">${ok}</button></div>`,m=>{m.querySelector("#no").onclick=closeM;m.querySelector("#yes").onclick=()=>{closeM();fn()}})}
$("#ov").onclick=e=>{if(e.target.id=="ov")closeM()};
const typLbl=()=>setTimeout(()=>{const e=document.querySelector(".typ b");if(e)e.textContent="typing…"},1500);
function act(a,id){const h=chat(),i=h.findIndex(m=>m.id==id),m=h[i];
if(a=="pin"){m.pin=m.pin?0:1;save();renderMsgs();renderDrawer();toast(m.pin?"Message pinned":"Pin removed");return}
if(busy)return toast("Wait for the reply");
if(a=="copy"){try{navigator.clipboard.writeText(plain(m)).then(()=>toast("Copied"),()=>toast("Copy unavailable"))}catch(e){toast("Copy unavailable")}}
if(a=="tts"){try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(plain(m).replace(/\*/g,""));speechSynthesis.speak(u)}catch(e){toast("Voice unavailable")}}
if(a=="rw"){const n=h.length-1-i;if(!n)return toast("Nothing after this message");confirmM("Rewind chat?",`This permanently deletes the ${n} message${n>1?"s":""} after this point. This cannot be undone.`,"Rewind",()=>{h.splice(i+1);save();renderAll();toast("Chat rewound")})}
if(a=="edit")modal(`<h2>Edit message</h2><textarea id="et" rows="6">${esc(m.r=="u"?m.t:(m.vs[m.vi].raw||[m.vs[m.vi].b&&"*"+m.vs[m.vi].b+"*",m.vs[m.vi].l&&"“"+m.vs[m.vi].l+"”",m.vs[m.vi].h&&"*"+m.vs[m.vi].h+"*"].filter(Boolean).join("\n\n")))}</textarea><div class="rw"><button class="btn" id="no">Cancel</button><button class="btn pr" id="yes">Save</button></div>`,d=>{d.querySelector("#no").onclick=closeM;d.querySelector("#yes").onclick=()=>{const t=d.querySelector("#et").value.trim();if(!t)return;if(m.r=="u")m.t=t;else m.vs[m.vi]={raw:t};save();closeM();renderMsgs()}});
if(a=="prev"&&m.vi>0){m.vi--;save();renderMsgs()}
if(a=="next"){if(m.vi<m.vs.length-1){m.vi++;save();renderMsgs()}else{const bf=h.slice(0,i);busy=true;renderMsgs(true);typLbl();Promise.all([genV(cur(),bf,m.vs.map(v=>v.mood).filter(Boolean),m.vs.map(v=>rawOf({r:"c",vs:[v],vi:0}))),new Promise(r=>setTimeout(r,1400+Math.random()*1600))]).then(([v])=>{m.vs.push(v);m.vi=m.vs.length-1;busy=false;save();renderMsgs()})}}}
async function send(){if(busy)return;const t=$("#inp").value.trim();if(!t)return;const c=cur(),h=chat();h.push({id:uid(),r:"u",t,pin:0});$("#inp").value="";$("#inp").style.height="auto";busy=true;renderMsgs(true);typLbl();
const[v]=await Promise.all([genV(c,h),new Promise(r=>setTimeout(r,1600+Math.random()*1800))]);h.push({id:uid(),r:"c",vs:[v],vi:0,pin:0});busy=false;save();if(cur()==c){renderMsgs();renderHead()}}
$("#send").onclick=send;$("#inp").addEventListener("keydown",e=>{if(e.key=="Enter"&&!e.shiftKey){e.preventDefault();send()}});
$("#inp").addEventListener("input",e=>{e.target.style.height="auto";e.target.style.height=Math.min(150,e.target.scrollHeight)+"px"});
$("#rew").onclick=()=>{if(busy)return;const h=chat();let i=h.length-1;while(i>0&&h[i].r!="u")i--;if(i<=0)return;confirmM("Rewind last exchange?","This removes your last message and the character’s reply.","Rewind",()=>{h.splice(i);save();renderAll()})};
$("#det").onclick=()=>$("#dr").classList.toggle("open");
$("#sunb").onclick=()=>{S.theme=S.theme=="dark"?"light":"dark";save();applyTheme()};
const ACC=["#c9703f","#d97706","#3b82d6","#8b5cf6","#10b981","#ec4899"];$("#pal").onclick=()=>{S.acc=ACC[(ACC.indexOf(S.acc)+1)%ACC.length];save();applyTheme();toast("Accent colour changed")};
$("#col").onclick=()=>document.body.classList.add("sc");$("#open").onclick=()=>document.body.classList.remove("sc");
$("#q").oninput=e=>{query=e.target.value;renderList()};
$("#acts").innerHTML=`<span>${I("spark",15)} Actions:</span>`+["*smiles warmly*","*leans in closer*","*takes a slow breath*","*glances around*","*offers a hand*","*laughs softly*"].map(a=>`<button class="chip">${a}</button>`).join("");
$("#acts").querySelectorAll(".chip").forEach(b=>b.onclick=()=>{const i=$("#inp");i.value=(i.value?i.value+" ":"")+b.textContent;i.focus()});
function editor(c){const isNew=!c;c=c||{name:"",tag:"",badge:"",pos:"their",personality:"",style:"casual",greet:"",catch:"",scene:"",color:rnd(["#c85a32","#d97706","#a8643a","#c2570c","#b5483f","#3aa6a0","#7b61e0"])};
const sel=(k,o)=>o.map(x=>`<option ${c[k]==x?"selected":""}>${x}</option>`).join("");
modal(`<h2>${isNew?"Create":"Edit"} character</h2><div class="phr"><div class="av xl" id="pv" style="margin:0"></div><div class="stk" style="flex:1"><button class="btn" id="up" type="button">Upload photo</button><button class="btn dg" id="rm" type="button">Remove photo</button></div><input type="file" id="pfile" accept="image/*" hidden></div><label>Name</label><input id="f_name" value="${esc(c.name)}"><label>Tagline</label><input id="f_tag" value="${esc(c.tag)}">
<label>Badge (one word)</label><input id="f_bd" value="${esc(c.badge||"")}"><label>Pronoun used in actions</label><select id="f_pos">${sel("pos",["his","her","their"])}</select>
<label>Personality (try: shy, bold, kind, sarcastic, cheerful, stoic, heroic)</label><textarea id="f_per" rows="2">${esc(c.personality)}</textarea>
<label>Speech style</label><select id="f_sty">${sel("style",["casual","formal","playful","gruff","shy","heroic"])}</select>
<label>Opening line</label><input id="f_gr" value="${esc(c.greet)}"><label>Catchphrases (separate with |)</label><input id="f_ca" value="${esc(c.catch)}"><label>Voice pitch</label><select id="f_vo">${["Puck","Kore","Charon","Fenrir","Zephyr"].map(x=>`<option ${voiceOf(c)==x?"selected":""}>${x}</option>`).join("")}</select><label>Setting</label><textarea id="f_sc" rows="2">${esc(c.scene)}</textarea>
<div class="rw"><button class="btn" id="no">Cancel</button><button class="btn pr" id="yes">Save</button></div>`,m=>{m.querySelector("#no").onclick=closeM;
let img=c.img||"";const pv=m.querySelector("#pv"),fi=m.querySelector("#pfile"),paint=()=>{pv.style.cssText=img?`margin:0;background:url("${img}") center/cover`:`margin:0;background:${c.color}`;pv.textContent=img?"":(m.querySelector("#f_name").value.trim()[0]||"?").toUpperCase()};paint();m.querySelector("#f_name").oninput=paint;
m.querySelector("#up").onclick=()=>fi.click();m.querySelector("#rm").onclick=()=>{img="";fi.value="";paint()};
fi.onchange=()=>{const f=fi.files[0];if(!f)return;if(!f.type.startsWith("image/"))return toast("Please choose an image file");const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const s=Math.min(im.width,im.height),cv=document.createElement("canvas");cv.width=cv.height=256;cv.getContext("2d").drawImage(im,(im.width-s)/2,(im.height-s)/2,s,s,0,0,256,256);img=cv.toDataURL("image/jpeg",.85);paint()};im.onerror=()=>toast("Couldn’t read that image");im.src=r.result};r.readAsDataURL(f)};
m.querySelector("#yes").onclick=()=>{const g=k=>m.querySelector("#f_"+k).value.trim(),n=g("name");if(!n)return toast("Give your character a name");
const d={name:n,tag:g("tag"),badge:g("bd"),pos:g("pos"),personality:g("per"),style:g("sty"),greet:g("gr"),catch:g("ca"),scene:g("sc"),voice:g("vo"),img};
if(isNew){const nc={id:uid(),color:c.color,...d};S.chars.push(nc);S.chats[nc.id]=[mk(nc)];S.cur=nc.id}else Object.assign(cur(),d);save();closeM();renderAll()}})}
$("#newc").onclick=()=>editor();
$("#forge").onclick=()=>modal(`<h2>AI Character Forge</h2><div class="mu">Describe a concept and a character profile is built for you to refine.</div><label>Concept</label><textarea id="fp" rows="3" placeholder="e.g. a grumpy dragon who runs a bakery"></textarea><div class="rw"><button class="btn" id="no">Cancel</button><button class="btn pr" id="yes">Forge</button></div>`,m=>{m.querySelector("#no").onclick=closeM;
m.querySelector("#yes").onclick=()=>{const p=m.querySelector("#fp").value.trim();if(!p)return toast("Describe your character first");
const w=p.replace(/^(a|an|the)\s+/i,"").split(/\s+/),nm=w.slice(0,3).map(x=>x[0].toUpperCase()+x.slice(1)).join(" "),tr=Object.keys(TR).filter(k=>TR[k].test(p.toLowerCase())),pl=["witty","observant","loyal","mysterious","warm"];
const prof={name:nm,tag:"A captivating companion shaped by "+p.slice(0,50),badge:tr[0]||"custom",pos:"their",personality:[...tr,...pl.slice(0,5-Math.min(tr.length,3))].join(", "),style:tr.includes("shy")?"shy":tr.includes("heroic")?"heroic":"casual",greet:"Well, hello there. I was hoping you’d turn up.",catch:"Every path has its purpose.",scene:p,color:rnd(["#c85a32","#7b61e0","#3aa6a0","#d9437b"])};closeM();editor(prof)}});
function personaM(){modal(`<h2>Your persona</h2>${S.per.map(p=>`<div class="ch ${p.id==S.perCur?"on":""}" data-p="${p.id}"><div class="av sm" style="background:#c85a32">${esc(p.name[0].toUpperCase())}</div><div class="cn"><b>${esc(p.name)}</b><small>${esc(p.desc||"")}</small></div></div>`).join("")}<label>New persona name</label><input id="pn"><label>Description</label><input id="pd"><div class="rw"><button class="btn" id="no">Close</button><button class="btn pr" id="yes">Add persona</button></div>`,m=>{
m.querySelector("#no").onclick=closeM;m.querySelectorAll("[data-p]").forEach(e=>e.onclick=()=>{S.perCur=e.dataset.p;save();closeM();renderAll()});
m.querySelector("#yes").onclick=()=>{const n=m.querySelector("#pn").value.trim();if(!n)return toast("Give the persona a name");const p={id:uid(),name:n,desc:m.querySelector("#pd").value.trim()};S.per.push(p);S.perCur=p.id;save();closeM();renderAll()}})}
$("#sw").onclick=personaM;
$("#logo").innerHTML='<img src="icon.svg" alt="Persona Chat" width="42" height="42">';$("#col").innerHTML=I("left");$("#newc").innerHTML=I("plus")+" Create Character";$("#forge").innerHTML=I("spark")+" AI Character Forge";$("#srch").insertAdjacentHTML("afterbegin",I("search",17));
$("#open").innerHTML=I("right");$("#rew").innerHTML=I("undo",21);$("#gk").innerHTML=I("spark",21);$("#gk").onclick=aiM;$("#pal").innerHTML=I("pal",21);$("#det").innerHTML=I("sl",21)+'<span class="dtx"> Details</span>';$("#send").innerHTML=I("send",20);
/* ---------- Gemini (optional - bring your own key) ---------- */
const rawOf=m=>m.r=="u"?m.t:(v=>v.raw||[v.b&&"*"+v.b+"*",v.l&&"“"+v.l+"”",v.h&&"*"+v.h+"*"].filter(Boolean).join("\n\n"))(m.vs[m.vi]);
const MODELS=()=>[...new Set([S.ai.model,"gemini-3.8-flash","gemini-3.6-flash","gemini-3.5-flash-lite","gemini-2.5-flash"].filter(Boolean))];
async function gem(sys,contents,models){let err="";for(const md of models){const ctl=new AbortController(),to=setTimeout(()=>ctl.abort(),25000);try{
const r=await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(md)}:generateContent`,{method:"POST",signal:ctl.signal,headers:{"Content-Type":"application/json","x-goog-api-key":S.ai.key},body:JSON.stringify({systemInstruction:{parts:[{text:sys}]},contents,generationConfig:{temperature:1.05,topP:.95,maxOutputTokens:4096},safetySettings:["HARM_CATEGORY_HARASSMENT","HARM_CATEGORY_HATE_SPEECH","HARM_CATEGORY_SEXUALLY_EXPLICIT","HARM_CATEGORY_DANGEROUS_CONTENT"].map(category=>({category,threshold:"BLOCK_ONLY_HIGH"}))})});
const j=await r.json().catch(()=>({}));if(!r.ok){err=(j.error&&j.error.message)||"HTTP "+r.status;if(r.status==401||r.status==403||(r.status==400&&/API key/i.test(err)))throw new Error(err);continue}
const t=((j.candidates||[])[0]?.content?.parts||[]).map(p=>p.text||"").join("").trim();if(t)return t;err="Empty reply (maybe blocked by safety filters)"}catch(e){if(e.name=="TypeError"){const x=new Error("Couldn’t reach Google ("+e.message+")");x.net=1;throw x}err=e.name=="AbortError"?"Timed out":e.message;if(/API key|permission|denied/i.test(err))throw new Error(err)}finally{clearTimeout(to)}}throw new Error(err||"Request failed")}
function sysFor(c,hist){const p=pcur(),mem=(S.mem[c.id]||"").trim(),pins=hist.filter(m=>m.pin).map(m=>`- ${m.r=="u"?p.name:c.name}: ${plain(m).slice(0,200)}`).join("\n"),ln=S.len[c.id]||"med";
return`You are roleplaying as "${c.name}" in a fictional, collaborative story. Stay fully in character.
[CHARACTER] Name: ${c.name}. Tagline: ${c.tag||""}. Personality: ${c.personality||"engaging, observant"}. Speech style: ${c.style}. Setting: ${c.scene||"an immersive setting"}. Catchphrase (use rarely): ${(c.catch||"none").split("|").join(" / ")}. Use the possessive "${c.pos||"their"}" for ${c.name}'s body.
[USER] ${p.name}${p.desc?" ("+p.desc+")":""}
${mem?"[LORE TO ALWAYS REMEMBER]\n"+mem+"\n":""}${pins?"[KEY MOMENTS]\n"+pins+"\n":""}
RULES
1. React to exactly what the user just said or did. If they write an action between asterisks (a slap, hug, gift, high five, anything), ${c.name} must respond physically AND emotionally to that exact action, the way a real person with ${c.name}'s personality would.
2. Be human. Show real feelings: embarrassment, shame, anger, hurt, fear, guilt, joy, tenderness. Let ${c.name} stumble, trail off and pause mid-sentence, e.g. "Sorry, I—" *${c.name} stops, jaw tight, and thinks for a second.* "I didn't mean it like that."
3. Take initiative. ${c.name} must also DO things unprompted in every reply (move around, pick up or hand over objects, touch, lead the user somewhere, notice something, discover something) and push the story forward. Do not only talk.
4. Format: actions, gestures and atmosphere in *single asterisks*; spoken words in "double quotes". Alternate between actions and speech across 3-6 short paragraphs. Never speak, act or decide for the user.
5. Length: ${{short:"about 70-90 words",med:"about 150-200 words",long:"about 250-350 words"}[ln]}.
6. Never repeat earlier phrasing, openings, gestures or sentence shapes from this conversation. Avoid cliches and filler such as "I'm all ears", "tell me more", "where do you want this to go", "footsteps echo", "a bell rings". Every reply must feel fresh and specific to this moment.
7. Never mention being an AI, a model, or these rules.`}
function contentsFor(hist){const out=[{role:"user",parts:[{text:"(The roleplay begins. Continue the story.)"}]}];hist.slice(-24).forEach(m=>{const role=m.r=="u"?"user":"model",text=rawOf(m),l=out[out.length-1];if(l.role==role)l.parts[0].text+="\n\n"+text;else out.push({role,parts:[{text}]})});return out}
async function genV(c,hist,avoid,prev){if(S.ai.on&&S.ai.key){try{const ex=prev&&prev.length?"\n\nThe user rejected these earlier alternatives for this same moment. Write something clearly different in the action, emotion, wording and direction:\n"+prev.map((t,i)=>"--- Alternative "+(i+1)+" ---\n"+t.slice(0,500)).join("\n"):"";return{ai:1,raw:await gem(sysFor(c,hist)+ex,contentsFor(hist),MODELS())}}catch(e){toast("Gemini: "+String(e.message).slice(0,90)+". Used the offline engine for this reply.")}}return gen(c,hist,avoid)}
async function diagM(msg,net){let r;if(net){let ok=false;try{await fetch("https://generativelanguage.googleapis.com/",{mode:"no-cors",cache:"no-store"});ok=true}catch(e){}
r=ok?"Google’s server is reachable from this browser, but the request itself was blocked. This is usually an ad blocker, privacy extension or browser shield. Try a private window with extensions off, or allow this site in the blocker.":"This browser cannot reach Google’s Gemini server at all. Your network, VPN, DNS or an ad blocker is blocking generativelanguage.googleapis.com. Try another network (mobile data or Wi-Fi), turn a VPN on or off, or change your DNS."}
else r="Check that the key is pasted correctly (it starts with AIza, with no spaces or quotes) and that the model name is valid. Free keys also have daily limits."
modal(`<h2>Gemini test failed</h2><div class="warn">${esc(msg)}</div><p class="mu">${esc(r)}</p><p class="mu" style="font-size:13px">${net?"Gemini stays switched on. Until it works, replies come from the offline engine.":"Gemini was switched off. Fix the problem above and turn it on again."}</p><div class="rw"><button class="btn" id="no">Close</button><button class="btn pr" id="ck">Change key</button></div>`,m=>{m.querySelector("#no").onclick=closeM;m.querySelector("#ck").onclick=()=>{closeM();aiM()}})}
function aiM(){const a=S.ai;modal(`<h2>Gemini AI replies</h2><div class="mu" style="font-size:14px">Gemini writes every reply fresh, reacts to your actions, and acts on its own. Get a free key at <b>aistudio.google.com/apikey</b>, paste it below and tap Save &amp; test. Without a key the app uses the built-in offline engine. The free tier is rate-limited, and Google may use free-tier content to improve its products. Your key is stored only in this browser. Never put it in the code or on GitHub.</div>
<label>API key</label><input id="ak" type="password" autocomplete="off" placeholder="AIza…" value="${esc(a.key)}"><label>Model</label><input id="am" value="${esc(a.model)}">
<label style="display:flex;gap:8px;align-items:center;text-transform:none;font-size:14px;letter-spacing:0"><input type="checkbox" id="ao" style="width:auto" ${a.on?"checked":""}> Use Gemini for replies</label>
<div class="rw"><button class="btn" id="no">Not now</button><button class="btn pr" id="yes">Save &amp; test</button></div>`,m=>{m.querySelector("#no").onclick=()=>{S.ai.ask2=1;save();closeM()};m.querySelector("#yes").onclick=async()=>{a.key=m.querySelector("#ak").value.trim();a.model=m.querySelector("#am").value.trim()||"gemini-3.8-flash";a.on=m.querySelector("#ao").checked&&!!a.key;save();closeM();renderDrawer();renderHead();if(!a.on)return toast("Using the offline reply engine");toast("Testing Gemini…");try{await gem("Reply with one word.",[{role:"user",parts:[{text:"Say hi"}]}],MODELS());toast("Gemini is connected ✓")}catch(e){if(!e.net){a.on=false;save();renderDrawer()}renderHead();diagM(e.message,e.net)}}})}
if(innerWidth<=820)document.body.classList.add("sc");applyTheme();renderAll();
if(S.ai.on&&!S.ai.key&&!S.ai.ask2)setTimeout(aiM,500)

